// Errores de dominio. Cada uno lleva un `status` HTTP para que la capa web
// pueda traducirlos sin conocer la lógica de negocio.

export class DomainError extends Error {
  constructor(message, { code = 'DOMAIN_ERROR', status = 400, details } = {}) {
    super(message);
    this.name = this.constructor.name;
    this.code = code;
    this.status = status;
    this.details = details;
  }
}

export class ValidationError extends DomainError {
  constructor(message, details) {
    super(message, { code: 'VALIDATION_ERROR', status: 400, details });
  }
}

export class NotFoundError extends DomainError {
  constructor(message) {
    super(message, { code: 'NOT_FOUND', status: 404 });
  }
}

/** Otro proceso modificó el carrito entre la lectura y la escritura. */
export class ConcurrencyError extends DomainError {
  constructor(cartId, expected, actual) {
    super(`Conflicto de versión en el carrito ${cartId}`, {
      code: 'VERSION_CONFLICT',
      status: 409,
      details: { expected, actual },
    });
  }
}

export class LimitExceededError extends DomainError {
  constructor(message, details) {
    super(message, { code: 'LIMIT_EXCEEDED', status: 422, details });
  }
}

export class OutOfStockError extends DomainError {
  constructor(sku, available) {
    super(`Stock insuficiente para ${sku}`, {
      code: 'OUT_OF_STOCK',
      status: 422,
      details: { sku, available },
    });
  }
}

// El dinero se representa SIEMPRE en unidades mínimas enteras (céntimos)
// para evitar errores de coma flotante (0.1 + 0.2 !== 0.3).

import { ValidationError } from './errors.js';

export function assertCents(value, field = 'importe') {
  if (!Number.isSafeInteger(value) || value < 0) {
    throw new ValidationError(`${field} debe ser un entero no negativo en céntimos`, { field, value });
  }
  return value;
}

/** Porcentaje aplicado a un importe, redondeo "half-up". `percent` admite decimales (21, 10.5...). */
export function percentOf(cents, percent) {
  return Math.round((cents * percent) / 100);
}

export function formatMoney(cents, currency = 'EUR', locale = 'es-ES') {
  return new Intl.NumberFormat(locale, { style: 'currency', currency }).format(cents / 100);
}

// Agregado Carrito.
//
// Es un objeto de datos plano (serializable a JSON tal cual) y las operaciones
// son funciones puras que devuelven un carrito NUEVO. Esto permite:
//   - guardarlo en cualquier almacén (memoria, Redis, DynamoDB...) sin mapeos;
//   - reintentar mutaciones ante conflictos de concurrencia sin efectos colaterales;
//   - testear el dominio sin infraestructura.

import { randomUUID } from 'node:crypto';
import { ValidationError, LimitExceededError, NotFoundError } from './errors.js';
import { assertCents } from './money.js';

export const DEFAULT_LIMITS = Object.freeze({
  maxLines: 100,          // productos distintos por carrito
  maxQuantityPerLine: 99, // unidades por producto
  maxCoupons: 5,
});

const SKU_RE = /^[A-Za-z0-9._-]{1,64}$/;
const COUPON_RE = /^[A-Za-z0-9_-]{1,32}$/;

export function assertSku(sku) {
  if (typeof sku !== 'string' || !SKU_RE.test(sku)) {
    throw new ValidationError('SKU inválido', { sku });
  }
  return sku;
}

export function assertQuantity(quantity, limits = DEFAULT_LIMITS) {
  if (!Number.isInteger(quantity) || quantity < 0) {
    throw new ValidationError('La cantidad debe ser un entero >= 0', { quantity });
  }
  if (quantity > limits.maxQuantityPerLine) {
    throw new LimitExceededError(`Máximo ${limits.maxQuantityPerLine} unidades por producto`, {
      quantity,
      max: limits.maxQuantityPerLine,
    });
  }
  return quantity;
}

export function normalizeCoupon(code) {
  if (typeof code !== 'string' || !COUPON_RE.test(code.trim())) {
    throw new ValidationError('Código de cupón inválido', { code });
  }
  return code.trim().toUpperCase();
}

export function createCart({ id = randomUUID(), ownerId = null, currency = 'EUR', now = Date.now() } = {}) {
  return {
    id,
    ownerId,
    currency,
    items: [],      // [{ sku, name, unitPrice, quantity, addedAt }]
    coupons: [],    // ['VERANO10', ...]
    version: 0,     // control de concurrencia optimista
    createdAt: now,
    updatedAt: now,
  };
}

function touch(cart, changes, now) {
  return { ...cart, ...changes, updatedAt: now };
}

/**
 * Fija la cantidad de un SKU (0 = eliminar). El precio y nombre vienen del
 * catálogo (nunca del cliente) y se actualizan en cada modificación.
 */
export function setItem(cart, { sku, name, unitPrice, quantity }, { limits = DEFAULT_LIMITS, now = Date.now() } = {}) {
  assertSku(sku);
  assertQuantity(quantity, limits);
  assertCents(unitPrice, 'unitPrice');

  const idx = cart.items.findIndex((i) => i.sku === sku);

  if (quantity === 0) {
    if (idx === -1) return cart;
    return touch(cart, { items: cart.items.filter((_, i) => i !== idx) }, now);
  }

  if (idx === -1) {
    if (cart.items.length >= limits.maxLines) {
      throw new LimitExceededError(`Máximo ${limits.maxLines} productos distintos por carrito`, {
        max: limits.maxLines,
      });
    }
    return touch(cart, { items: [...cart.items, { sku, name, unitPrice, quantity, addedAt: now }] }, now);
  }

  const items = cart.items.slice();
  items[idx] = { ...items[idx], name, unitPrice, quantity };
  return touch(cart, { items }, now);
}

export function getQuantity(cart, sku) {
  return cart.items.find((i) => i.sku === sku)?.quantity ?? 0;
}

export function removeItem(cart, sku, { now = Date.now() } = {}) {
  assertSku(sku);
  if (!cart.items.some((i) => i.sku === sku)) {
    throw new NotFoundError(`El producto ${sku} no está en el carrito`);
  }
  return touch(cart, { items: cart.items.filter((i) => i.sku !== sku) }, now);
}

export function addCoupon(cart, code, { limits = DEFAULT_LIMITS, now = Date.now() } = {}) {
  const normalized = normalizeCoupon(code);
  if (cart.coupons.includes(normalized)) return cart;
  if (cart.coupons.length >= limits.maxCoupons) {
    throw new LimitExceededError(`Máximo ${limits.maxCoupons} cupones`, { max: limits.maxCoupons });
  }
  return touch(cart, { coupons: [...cart.coupons, normalized] }, now);
}

export function removeCoupon(cart, code, { now = Date.now() } = {}) {
  const normalized = normalizeCoupon(code);
  if (!cart.coupons.includes(normalized)) {
    throw new NotFoundError(`El cupón ${normalized} no está aplicado`);
  }
  return touch(cart, { coupons: cart.coupons.filter((c) => c !== normalized) }, now);
}

export function clearCart(cart, { now = Date.now() } = {}) {
  return touch(cart, { items: [], coupons: [] }, now);
}

/** Cantidades combinadas de dos carritos (p. ej. carrito de invitado + carrito del usuario al hacer login). */
export function mergedQuantities(target, source, limits = DEFAULT_LIMITS) {
  const result = new Map(target.items.map((i) => [i.sku, i.quantity]));
  for (const item of source.items) {
    const q = (result.get(item.sku) ?? 0) + item.quantity;
    result.set(item.sku, Math.min(q, limits.maxQuantityPerLine));
  }
  return result;
}

// Motor de precios basado en reglas enchufables (patrón Strategy).
//
// Cada regla es un objeto { id, type, ...params } y se evalúa con un
// "evaluador" registrado para su tipo. Añadir un nuevo tipo de promoción no
// requiere tocar el carrito ni el servicio: solo registrar un evaluador.
//
// Orden de cálculo:
//   1. subtotal = Σ unitPrice × quantity
//   2. descuentos de línea (p. ej. 3x2)
//   3. descuentos de pedido (p. ej. -10 % a partir de 50 €)
//   4. envío (con reglas de envío gratis)
//   5. impuestos sobre (subtotal - descuentos + envío)   [precios sin IVA]

import { percentOf } from './money.js';

const evaluators = new Map();

/** Registra un tipo de regla. `fn(rule, ctx) => [{ ruleId, label, amount }]` (amount en céntimos, positivo). */
export function registerRuleType(type, fn) {
  evaluators.set(type, fn);
}

// ---- Tipos de regla incluidos ------------------------------------------------

// Porcentaje sobre el pedido, opcionalmente con mínimo de compra.
registerRuleType('percent_off_order', (rule, ctx) => {
  if (ctx.subtotalAfterLineDiscounts < (rule.minSubtotal ?? 0)) return [];
  const amount = percentOf(ctx.subtotalAfterLineDiscounts, rule.percent);
  return amount > 0 ? [{ ruleId: rule.id, label: rule.label ?? `-${rule.percent}%`, amount }] : [];
});

// Importe fijo sobre el pedido, opcionalmente con mínimo de compra.
registerRuleType('fixed_off_order', (rule, ctx) => {
  if (ctx.subtotalAfterLineDiscounts < (rule.minSubtotal ?? 0)) return [];
  const amount = Math.min(rule.amount, ctx.subtotalAfterLineDiscounts);
  return amount > 0 ? [{ ruleId: rule.id, label: rule.label ?? 'Descuento', amount }] : [];
});

// Porcentaje sobre productos concretos.
registerRuleType('percent_off_skus', (rule, ctx) => {
  const skus = new Set(rule.skus);
  return ctx.lines
    .filter((l) => skus.has(l.sku))
    .map((l) => ({ ruleId: rule.id, label: rule.label ?? `-${rule.percent}% ${l.sku}`, sku: l.sku, amount: percentOf(l.lineTotal, rule.percent) }))
    .filter((d) => d.amount > 0);
});

// Lleva X, paga Y (3x2) sobre productos concretos.
registerRuleType('buy_x_pay_y', (rule, ctx) => {
  const skus = new Set(rule.skus);
  return ctx.lines
    .filter((l) => skus.has(l.sku))
    .map((l) => {
      const free = Math.floor(l.quantity / rule.buy) * (rule.buy - rule.pay);
      return { ruleId: rule.id, label: rule.label ?? `${rule.buy}x${rule.pay} ${l.sku}`, sku: l.sku, amount: free * l.unitPrice };
    })
    .filter((d) => d.amount > 0);
});

const LINE_RULES = new Set(['percent_off_skus', 'buy_x_pay_y']);

// ---- Cálculo -----------------------------------------------------------------

/**
 * @param cart     carrito del dominio
 * @param options  { rules: [], taxRate: 21, shipping: { flat, freeOver } }
 */
export function priceCart(cart, { rules = [], taxRate = 0, shipping = { flat: 0, freeOver: null } } = {}) {
  const lines = cart.items.map((i) => ({
    sku: i.sku,
    name: i.name,
    unitPrice: i.unitPrice,
    quantity: i.quantity,
    lineTotal: i.unitPrice * i.quantity,
  }));
  const subtotal = lines.reduce((s, l) => s + l.lineTotal, 0);

  const known = rules.filter((r) => evaluators.has(r.type));
  const lineRules = known.filter((r) => LINE_RULES.has(r.type));
  const orderRules = known.filter((r) => !LINE_RULES.has(r.type));

  const ctx = { lines, subtotal, subtotalAfterLineDiscounts: subtotal };
  const discounts = [];

  for (const rule of lineRules) discounts.push(...evaluators.get(rule.type)(rule, ctx));
  // Un descuento de línea nunca puede superar el importe de la línea.
  capLineDiscounts(discounts, lines);
  ctx.subtotalAfterLineDiscounts = subtotal - sum(discounts);

  for (const rule of orderRules) {
    const produced = evaluators.get(rule.type)(rule, ctx);
    discounts.push(...produced);
    ctx.subtotalAfterLineDiscounts -= sum(produced);
  }

  const discountTotal = Math.min(sum(discounts), subtotal);
  const net = subtotal - discountTotal;

  const freeShipping = shipping.freeOver != null && net >= shipping.freeOver;
  const shippingCost = lines.length === 0 || freeShipping ? 0 : (shipping.flat ?? 0);

  const taxable = net + shippingCost;
  const tax = percentOf(taxable, taxRate);

  return {
    currency: cart.currency,
    lines,
    itemCount: lines.reduce((s, l) => s + l.quantity, 0),
    subtotal,
    discounts,
    discountTotal,
    shipping: shippingCost,
    taxRate,
    tax,
    total: taxable + tax,
  };
}

function sum(list) {
  return list.reduce((s, d) => s + d.amount, 0);
}

function capLineDiscounts(discounts, lines) {
  const remaining = new Map(lines.map((l) => [l.sku, l.lineTotal]));
  for (const d of discounts) {
    const left = remaining.get(d.sku) ?? 0;
    d.amount = Math.min(d.amount, left);
    remaining.set(d.sku, left - d.amount);
  }
  for (let i = discounts.length - 1; i >= 0; i--) if (discounts[i].amount === 0) discounts.splice(i, 1);
}

